/// The capabilities the UI gets (M1.7, #82 M1; M5.1 B1), checked with
/// Tauri's own ACL resolver against the manifests and capabilities the
/// build script produced for this build, and by invoking the real commands
/// on Tauri's mock runtime with that ACL.
#[cfg(test)]
mod capability_tests {
    use std::collections::BTreeMap;
    use std::path::PathBuf;

    use tauri::ipc::{CallbackFn, InvokeBody, RuntimeAuthority};
    use tauri::test::{
        INVOKE_KEY, MockRuntime, get_ipc_response, mock_builder, mock_context, noop_assets,
    };
    use tauri::webview::InvokeRequest;
    use tauri::{App, Manager as _, WebviewWindow, WebviewWindowBuilder};
    use tauri_utils::acl::ExecutionContext;
    use tauri_utils::acl::capability::Capability;
    use tauri_utils::acl::manifest::Manifest;
    use tauri_utils::acl::resolved::Resolved;
    use tauri_utils::platform::Target;

    use super::AppConfig;
    use crate::command_names::COMMAND_NAMES;
    use crate::engine::LiveEngine;

    /// The settings window: the app's commands.
    const MAIN: &str = "main";
    /// The overlay window (M5.1): listening to events and nothing else.
    const OVERLAY: &str = "overlay";
    const OVERLAY_COMMANDS: [&str; 2] = ["plugin:event|listen", "plugin:event|unlisten"];

    fn manifests() -> BTreeMap<String, Manifest> {
        let path = PathBuf::from(env!("OUT_DIR")).join("acl-manifests.json");
        serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
    }

    fn resolved() -> Resolved {
        let path = PathBuf::from(env!("OUT_DIR")).join("capabilities.json");
        let capabilities: BTreeMap<String, Capability> =
            serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
        Resolved::resolve(&manifests(), capabilities, Target::current()).unwrap()
    }

    /// The windows each allowed command is allowed in.
    fn allowed_windows() -> BTreeMap<String, Vec<String>> {
        resolved()
            .allowed_commands
            .into_iter()
            .map(|(name, commands)| {
                let mut windows = Vec::new();
                for command in commands {
                    assert!(command.webviews.is_empty(), "{name}: by webview");
                    windows.extend(command.windows.iter().map(|w| w.as_str().to_owned()));
                }
                (name, windows)
            })
            .collect()
    }

    /// The capability files the build script resolved, as JSON, to mutate.
    fn capability_files() -> serde_json::Value {
        let out_dir = PathBuf::from(env!("OUT_DIR"));
        serde_json::from_str(&std::fs::read_to_string(out_dir.join("capabilities.json")).unwrap())
            .unwrap()
    }

    fn resolve(capabilities: serde_json::Value) -> Resolved {
        let out_dir = PathBuf::from(env!("OUT_DIR"));
        let manifests: BTreeMap<String, Manifest> = serde_json::from_str(
            &std::fs::read_to_string(out_dir.join("acl-manifests.json")).unwrap(),
        )
        .unwrap();
        let capabilities: BTreeMap<String, Capability> =
            serde_json::from_value(capabilities).unwrap();
        Resolved::resolve(&manifests, capabilities, Target::current()).unwrap()
    }

    /// What each window may call, and nothing more: the settings window
    /// (`main`) every app command, the overlay only its event listening, both
    /// from the app's own (local) pages only, so no tray, menu, resource or
    /// window mutation anywhere and no remote origin. `Err` names the first
    /// breach.
    fn check_windows(resolved: &Resolved) -> Result<(), String> {
        for name in COMMAND_NAMES {
            if !resolved.allowed_commands.contains_key(*name) {
                return Err(format!(
                    "{name} is not allowed; the settings window needs it"
                ));
            }
        }
        for (command, grants) in &resolved.allowed_commands {
            let window = if COMMAND_NAMES.contains(&command.as_str()) {
                MAIN
            } else if OVERLAY_COMMANDS.contains(&command.as_str()) {
                OVERLAY
            } else {
                return Err(format!("{command} is allowed"));
            };
            for grant in grants {
                if let ExecutionContext::Remote { url } = &grant.context {
                    return Err(format!("remote origin {url:?} may call {command}"));
                }
                let windows: Vec<&str> = grant.windows.iter().map(|w| w.as_str()).collect();
                if windows != [window] || !grant.webviews.is_empty() {
                    return Err(format!(
                        "{command} reaches {windows:?} {:?}",
                        grant.webviews
                    ));
                }
            }
        }
        Ok(())
    }

    /// T2 criterion 3 (#103 P2-01): checked with Tauri's own ACL resolver on
    /// this build's manifests, and shown to fail if a tray, menu, resource or
    /// window permission, or a remote origin, is added to either window's
    /// capability, or an app command is taken from the settings window.
    #[test]
    fn main_capability_denies_native_tray_and_menu_mutation() {
        let real = capability_files();
        assert_eq!(check_windows(&resolve(real.clone())), Ok(()));

        for permission in [
            "core:default",
            "core:tray:default",
            "core:tray:allow-set-menu",
            "core:tray:allow-set-visible",
            "core:menu:default",
            "core:menu:allow-set-enabled",
            "core:resources:allow-close",
            "core:window:allow-hide",
        ] {
            for capability in ["default", OVERLAY] {
                let mut widened = real.clone();
                widened[capability]["permissions"]
                    .as_array_mut()
                    .unwrap()
                    .push(permission.into());
                let breach = check_windows(&resolve(widened));
                assert!(
                    breach.is_err(),
                    "adding {permission} to {capability} went unnoticed"
                );
            }
        }

        for capability in ["default", OVERLAY] {
            let mut remote = real.clone();
            remote[capability]["remote"] = serde_json::json!({ "urls": ["https://*.example.com"] });
            let breach = check_windows(&resolve(remote)).unwrap_err();
            assert!(breach.contains("remote origin"), "{capability}: {breach}");
        }

        let mut narrowed = real;
        narrowed["default"]["permissions"]
            .as_array_mut()
            .unwrap()
            .retain(|permission| permission != "allow-save-settings");
        let breach = check_windows(&resolve(narrowed)).unwrap_err();
        assert!(breach.contains("save_settings"), "{breach}");
    }

    #[test]
    fn criterion_m1_7_2_main_may_call_only_the_app_commands() {
        let mut expected: BTreeMap<String, Vec<String>> = COMMAND_NAMES
            .iter()
            .map(|name| ((*name).to_owned(), vec![MAIN.to_owned()]))
            .collect();
        // M5.1 B1: the overlay listens to its event, nothing more, and no
        // app command reaches it.
        for command in OVERLAY_COMMANDS {
            expected.insert(command.to_owned(), vec![OVERLAY.to_owned()]);
        }
        assert_eq!(
            allowed_windows(),
            expected,
            "nothing else from core: or any plugin"
        );
    }

    #[test]
    fn criterion_m1_7_2_the_tray_and_menus_are_out_of_reach() {
        let allowed = resolved().allowed_commands;
        for command in [
            "plugin:tray|get_by_id",
            "plugin:tray|remove_by_id",
            "plugin:tray|set_visible",
            "plugin:tray|set_menu",
            "plugin:menu|set_enabled",
            "plugin:resources|close",
            "plugin:window|hide",
            "plugin:event|emit",
            "plugin:event|emit_to",
        ] {
            assert!(!allowed.contains_key(command), "{command} is allowed");
        }
    }

    fn capability_file(name: &str) -> serde_json::Value {
        let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("capabilities")
            .join(name);
        serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
    }

    #[test]
    fn criterion_m1_7_2_the_capability_files_list_exactly_the_commands() {
        let dir = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("capabilities");
        let mut files: Vec<_> = std::fs::read_dir(&dir)
            .unwrap()
            .map(|entry| entry.unwrap().file_name())
            .collect();
        files.sort();
        assert_eq!(
            files,
            ["default.json", "overlay.json"],
            "two capability files"
        );

        let main = capability_file("default.json");
        let expected: Vec<String> = COMMAND_NAMES
            .iter()
            .map(|name| format!("allow-{}", name.replace('_', "-")))
            .collect();
        assert_eq!(main["permissions"], serde_json::json!(expected));
        assert_eq!(main["windows"], serde_json::json!([MAIN]));
        assert!(main.get("webviews").is_none());
        assert!(main.get("remote").is_none());

        let overlay = capability_file("overlay.json");
        assert_eq!(
            overlay["permissions"],
            serde_json::json!(["core:event:allow-listen", "core:event:allow-unlisten"])
        );
        assert_eq!(overlay["windows"], serde_json::json!([OVERLAY]));
        assert!(overlay.get("webviews").is_none());
        assert!(overlay.get("remote").is_none());
    }

    /// The app on Tauri's mock runtime with this build's ACL and the real
    /// command handler, its settings in a fresh directory (no keychain call
    /// is made by the commands invoked below), and a window per label.
    fn app_with_windows(labels: &[&str]) -> (App<MockRuntime>, Vec<WebviewWindow<MockRuntime>>) {
        let manifests = manifests();
        let resolved = resolved();
        assert!(resolved.has_app_acl, "build.rs declares the app manifest");
        let mut context = mock_context(noop_assets());
        *context.runtime_authority_mut() = RuntimeAuthority::new(manifests, resolved);
        let app = mock_builder()
            .invoke_handler(super::builder::<MockRuntime>().invoke_handler())
            .build(context)
            .unwrap();
        let dir = std::env::temp_dir().join(format!(
            "dictation-acl-{}-{}",
            std::process::id(),
            labels.join("-")
        ));
        app.manage(AppConfig(std::sync::Arc::new(
            dictation_pipeline::config::Config::new(
                &dir,
                dictation_platform::secrets::KeychainSecretStore::new(),
            ),
        )));
        app.manage(crate::commands::LoginItem(std::sync::Arc::new(
            dictation_platform::fakes::FakeLaunchAtLogin::new(),
        )));
        app.manage(LiveEngine::fixed());
        app.manage(super::ActiveHotkey(super::tests::hotkey::listening().0));
        app.manage(std::sync::Arc::new(crate::onboarding::Onboarding::new()));
        app.manage(crate::onboarding::OsPermissions(std::sync::Arc::new(
            dictation_platform::fakes::FakePermissions::all_granted(),
        )));
        app.manage(super::ConfigDir(dir.clone()));
        app.manage(super::AppShell(std::sync::Arc::new(NoShell)));
        let windows = labels
            .iter()
            .map(|label| {
                WebviewWindowBuilder::new(&app, *label, tauri::WebviewUrl::default())
                    .build()
                    .unwrap()
            })
            .collect();
        (app, windows)
    }

    /// The app itself, without a window to hide or a process to restart.
    struct NoShell;

    impl super::Shell for NoShell {
        fn hide_window(&self) {}
        fn restart(&self) {}
    }

    fn invoke(
        window: &WebviewWindow<MockRuntime>,
        command: &str,
        args: serde_json::Value,
    ) -> Result<tauri::ipc::InvokeResponseBody, serde_json::Value> {
        get_ipc_response(
            window,
            InvokeRequest {
                cmd: command.into(),
                callback: CallbackFn(0),
                error: CallbackFn(1),
                url: "tauri://localhost".parse().unwrap(),
                body: InvokeBody::Json(args),
                headers: tauri::http::HeaderMap::default(),
                invoke_key: INVOKE_KEY.into(),
            },
        )
    }

    /// Valid arguments for each command, so a refusal can only be the ACL's.
    fn args(command: &str) -> serde_json::Value {
        match command {
            "save_settings" => {
                serde_json::json!({ "settings": dictation_core::settings::Settings::default() })
            }
            "set_api_key" => serde_json::json!({ "provider": "groq", "key": "gsk_not_a_real_key" }),
            "has_api_key" | "test_api_key" => serde_json::json!({ "provider": "groq" }),
            "request_permission" => serde_json::json!({ "permission": "microphone" }),
            "set_onboarding_step" => serde_json::json!({ "step": "microphone" }),
            _ => serde_json::json!({}),
        }
    }

    /// M5.1 B1: the overlay can't call any app command, though it's a local
    /// window of this app; the ACL refuses before the command runs.
    #[test]
    fn criterion_m5_1_2_the_overlay_may_not_invoke_any_app_command() {
        let (_app, windows) = app_with_windows(&[OVERLAY]);
        for command in COMMAND_NAMES {
            let error = invoke(&windows[0], command, args(command)).unwrap_err();
            let message = error.to_string();
            assert!(message.contains("not allowed"), "{command}: {message}");
        }
    }

    /// Arguments the command can't take: the ACL has already let the call
    /// through when they are rejected, and the command itself never runs,
    /// so no keychain or network is touched.
    fn unusable_args() -> serde_json::Value {
        serde_json::json!({
            "provider": "not-a-provider",
            "settings": 0,
            "key": 0,
            "permission": "camera",
            "step": "done",
        })
    }

    /// M5.1 criterion 2 and #110: ...while the settings window may call
    /// every app command through the real handler, so a command left out of
    /// its grant fails here instead of breaking Settings at run time.
    /// `get_settings` and `save_settings` touch only the settings file; the
    /// keychain and network commands are called with arguments they refuse,
    /// which the ACL checks before. (What the capability files grant, and
    /// that widening or narrowing them is caught, is
    /// `main_capability_denies_native_tray_and_menu_mutation`, on Tauri's
    /// resolver; this is the same ACL at run time.)
    #[test]
    fn the_settings_window_may_invoke_all_ten_app_commands() {
        let (_app, windows) = app_with_windows(&[MAIN, OVERLAY]);
        let (main, overlay) = (&windows[0], &windows[1]);
        for command in COMMAND_NAMES {
            let reached = match *command {
                // No keychain, network or OS prompt: the onboarding ones
                // run on fakes (granted permissions, no shell).
                "get_settings" | "save_settings" | "get_onboarding" | "finish_onboarding"
                | "relaunch_app" => invoke(main, command, args(command)).map(|_| ()),
                _ => match invoke(main, command, unusable_args()) {
                    Err(error) if error.to_string().contains("invalid args") => Ok(()),
                    other => other.map(|_| ()),
                },
            };
            assert_eq!(reached, Ok(()), "main couldn't call {command}");
            // The same unusable call from the overlay is refused by the ACL,
            // so the arguments' error above really comes after it.
            let refused = invoke(overlay, command, unusable_args()).unwrap_err();
            assert!(
                refused.to_string().contains("not allowed"),
                "{command}: {refused}"
            );
        }
        assert_eq!(COMMAND_NAMES.len(), 10);
    }

    #[test]
    fn the_command_names_are_the_registered_commands() {
        let bindings = std::fs::read_to_string(
            PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(super::BINDINGS_PATH),
        )
        .unwrap();
        let invoked: Vec<&str> = bindings
            .split("__TAURI_INVOKE(\"")
            .skip(1)
            .filter_map(|rest| rest.split_once('"').map(|(name, _)| name))
            .collect();
        assert_eq!(invoked, COMMAND_NAMES);
    }
}
